/*!40000 ALTER TABLE `traveltips` DISABLE KEYS */;
INSERT INTO `traveltips` (`tt_id`, `tt_section`, `tt_order`, `tt_header`, `tt_question`, `tt_answer`, `tt_extra`, `tt_cta_type`, `tt_cta_label`, `tt_cta_value`) VALUES (1,'a',1,'Mobile Services','\"Where is the most convenient place to purchase a local 5G prepaid SIM card upon arrival?\"','You can find dedicated service provider kiosks from Maxis, CelcomDigi, and U Mobile immediately after exiting the international arrival gates at KLIA 1 & KLIA 2. These counters operate 24 hours a day and offer tourist-specific data packages starting from RM15 for 7-day unlimited plans.','','map','Find SIM Shops','Maxis CelcomDigi U Mobile SIM card shop'),(2,'a',2,'Calling Logistics','\"How do I make affordable international calls back home while in KL?\"','The easiest method is to use internet-based apps like WhatsApp, Telegram, or FaceTime over your local data plan — these are free and widely used in Malaysia. For traditional calls, purchase a prepaid SIM with an international calling add-on from Maxis or CelcomDigi, offering rates from as low as RM0.09 per minute to most countries.','','link','Compare Call Rates','https://www.gulfsip.com/rates/calls/Malaysia'),(3,'a',3,'Online Access','\"Is free public WiFi widely available across Kuala Lumpur?\"','Yes! KL offers free WiFi under the \'KL Free WiFi\' initiative at over 5,000 hotspots covering LRT/MRT stations, shopping malls, public parks, and major tourist attractions. Simply search for \"KL Free WiFi\" on your device. For faster, consistent connectivity, a local prepaid data SIM remains the most reliable option for extended stays.','','link','Find WiFi Hotspots','https://www.google.com/maps/search/free+wifi+near+me/'),(4,'b',1,'Safety','\"Which areas of KL should I be cautious in, and what are the most common tourist scams to avoid?\"','Kuala Lumpur is a safe and welcoming destination for most visitors, with popular areas such as Bukit Bintang, KLCC, and Petaling Street attracting millions of tourists each year. As in any major city, visitors should stay aware of their surroundings in crowded places and be cautious of common issues such as taxi overcharging, counterfeit goods, and unofficial ticket sellers. Using ride-hailing apps, securing valuables, and purchasing from trusted sources are simple steps that help ensure a smooth and enjoyable visit.','','none','',''),(5,'b',2,'Environment','\"Are there any environmental laws or local practices I should be aware of as a visitor in KL?\"','Malaysia enforces strict anti-littering laws with fines up to RM500. Smoking is banned in all air-conditioned public spaces, restaurants, bars, and within 3 metres of any food premises — penalties can reach RM10,000. Many malls and attractions have gone plastic-bag-free, so carrying a reusable tote is strongly recommended. Haze season (June–October) can occasionally affect air quality; check the daily API index before outdoor activities.','','link','Read Local Rules','https://www.elaw.my/Default.aspx?returnUrl=https%3a%2f%2fwww.elaw.my%2f'),(6,'c',1,'Legal','\"What are the key laws tourists most commonly and unknowingly break in Malaysia?\"','Drug possession carries a mandatory death penalty in Malaysia — never carry any controlled substances across the border or within the country. Public displays of affection can result in fines. Jaywalking is a ticketable offence. When visiting mosques or Hindu temples, dress modestly by covering shoulders and knees; many mosques such as Masjid Negara provide loaner robes free of charge at the entrance.','<p class=\"tt-legal-sub\">Key Local Laws and Cultural Norms</p>\n                    <ul class=\"tt-legal-list\">\n                      <li><strong>Drugs:</strong> Malaysia has mandatory death penalties for drug trafficking and strict penalties for possession.</li>\n                      <li><strong>Public Behavior:</strong> Public displays of affection (PDA) are frowned upon; public nudity or indecent clothing can lead to arrest.</li>\n                      <li><strong>Alcohol/Smoking:</strong> Alcohol is not served everywhere, especially in rural areas. Smoking is prohibited in most public spaces.</li>\n                      <li><strong>Dress Code:</strong> Dress conservatively, especially at religious sites. Covering shoulders and knees is advised.</li>\n                    </ul>','none','',''),(7,'c',2,'Currency','\"Where is the best place to exchange foreign currency for the most competitive rates in KL?\"','Licensed money changers inside major malls — such as Suria KLCC, Pavilion KL, and Mid Valley Megamall — consistently offer rates far superior to airport exchange counters or bank branches. Avoid hotel exchange desks. ATMs on the Visa or Mastercard network are widely available citywide and offer competitive mid-market rates. The Malaysian Ringgit (MYR / RM) is the sole legal tender.','','link','Find Money Changers','https://www.google.com/maps/search/money+changer+near+me/'),(8,'d',1,'Apparel','\"What should I pack to wear in KL given its multicultural environment and tropical climate?\"','Opt for lightweight, breathable fabrics like cotton or linen to cope with constant heat and humidity. Casual wear is perfectly acceptable in malls and tourist areas. Pack a light shawl or sarong for mosque and temple visits — shoulders and knees must be covered. Many mosques such as Masjid Negara provide loaner robes at the entrance at no charge. Comfortable closed-toe walking shoes are a must for KL\'s hilly terrain and tiled surfaces.','','none','',''),(9,'d',2,'Weather Protection','\"How do I best prepare for KL\'s intense sun and sudden heavy rainstorms?\"','Always carry a compact umbrella or light rain poncho — heavy afternoon downpours between 3pm and 5pm are extremely common, particularly from October to March during the Northeast Monsoon season. Apply SPF50+ sunscreen daily, as UV Index levels regularly reach \"Extreme\" (11+). Stay well-hydrated; the combination of tropical heat and high humidity can cause fatigue and dehydration quickly.','','link','Check KL Weather','https://www.google.com/search?q=weather+in+kuala+lumpur'),(10,'d',3,'Health','\"Do I need any vaccinations or special medications before travelling to Kuala Lumpur?\"','No mandatory vaccinations are required to enter Malaysia for most nationalities. However, the WHO recommends being current on Hepatitis A & B and Typhoid vaccines for travel to KL. Dengue fever is present year-round, so apply DEET-based mosquito repellent especially in parks and forested areas like FRIM or Bukit Nanas. Tap water is treated but bottled or filtered water is widely preferred by both residents and visitors.','','none','',''),(11,'e',1,'Accommodation','\"Which neighbourhood in KL is the best base for first-time visitors who plan to rely on public transport?\"','The Golden Triangle area — spanning Bukit Bintang, KLCC, and Chow Kit — is ideal for first-time visitors. It provides direct access to multiple LRT, MRT, and Monorail lines, is walkable to iconic attractions including the Petronas Twin Towers, Berjaya Times Square, and Pavilion KL, and offers accommodation at every price point from budget guesthouses and hostels to international 5-star hotels.','','map','Find Nearby Hotels','hotels near me');
